using System; using System.Diagnostics; using System.IO; using System.Linq; using System.Text.Json; using System.Threading.Tasks; using System.Windows; using System.Windows.Controls; using System.Windows.Media;
namespace Prometheus.PRK.Controller;
public partial class MainWindow:Window {
 string Root=>Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"..")); string Tool=>Path.Combine(Root,"tools","Prometheus-PRK-SelfRepair.ps1"); string RecoveryTool=>Path.Combine(Root,"tools","Prometheus-Recovery-Key.ps1"); string Drive=>Path.GetPathRoot(Root)?.TrimEnd('\\')??""; string Local=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Prometheus"); string Log=>Path.Combine(Local,"Recovery","self-repair.log");
 Button[] ActionButtons=>new[]{DiagnosticsButton,VerifyButton,StageButton,BootstrapButton,RepairButton,RefreshButton,EjectButton};
 public MainWindow(){InitializeComponent();Loaded+=async(_,__)=>await RefreshHealthAsync();}
 Brush B(string state)=>new SolidColorBrush((Color)ColorConverter.ConvertFromString(state is "ready" or "armed"?"#35D07F":state is "repairable" or "working"?"#E4B72C":"#E34D59"));
 async Task<(int code,string output,string error)> RunProcessAsync(string file,string args){var p=new ProcessStartInfo(file,args){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};using var x=Process.Start(p)!;var so=x.StandardOutput.ReadToEndAsync();var se=x.StandardError.ReadToEndAsync();await x.WaitForExitAsync();return(x.ExitCode,await so,await se);}
 async Task<string> RunEngineAsync(string action){var r=await RunProcessAsync("powershell.exe",$"-NoProfile -ExecutionPolicy Bypass -File \"{Tool}\" -Action {action} -Drive \"{Drive}\"");if(r.code!=0)throw new Exception(string.IsNullOrWhiteSpace(r.error)?"Recovery engine failed.":r.error.Trim());return r.output;}
 async Task<string> RunRecoveryAsync(string action){var r=await RunProcessAsync("powershell.exe",$"-NoProfile -ExecutionPolicy Bypass -File \"{RecoveryTool}\" -Action {action} -Drive \"{Drive}\"");if(r.code!=0)throw new Exception(string.IsNullOrWhiteSpace(r.error)?$"{action} failed.":r.error.Trim());return r.output;}
 void Busy(string operation){foreach(var b in ActionButtons)b.IsEnabled=false;StatusText.Text=$"STATUS: {operation.ToUpperInvariant()}";StatusText.Foreground=B("working");StatusBorder.BorderBrush=B("working");CurrentStateText.Text=operation.ToUpperInvariant();DetailText.Text="Operation in progress. Please wait.";LogText.Text=$"{DateTime.Now:G} — {operation} started.";}
 void Enable(){foreach(var b in ActionButtons)b.IsEnabled=true;}
 async Task RefreshHealthAsync(){Busy("Checking health");try{using var j=JsonDocument.Parse(await RunEngineAsync("health"));RenderHealth(j.RootElement);}catch(Exception ex){SetError(ex.Message);}finally{Enable();}}
 void RenderHealth(JsonElement r){HealthPanel.Children.Clear();var states=r.GetProperty("channels").EnumerateArray().Select(x=>x.Clone()).ToArray();var error=states.Any(c=>c.GetProperty("state").GetString() is "error" or "blocked");var repairable=states.Any(c=>c.GetProperty("state").GetString()=="repairable");var overall=error?"error":repairable?"repairable":"ready";var avg=(int)states.Average(c=>c.GetProperty("percent").GetInt32());foreach(var c in states){var name=c.GetProperty("name").GetString()??"";var state=c.GetProperty("state").GetString()??"";var pct=c.GetProperty("percent").GetInt32();var detail=c.GetProperty("detail").GetString()??"";var g=new Grid{Margin=new Thickness(0,1,0,2)};g.RowDefinitions.Add(new RowDefinition());g.RowDefinitions.Add(new RowDefinition());g.RowDefinitions.Add(new RowDefinition());g.ColumnDefinitions.Add(new ColumnDefinition());g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(150)});var n=new TextBlock{Text=name.Replace("_"," ").ToUpperInvariant(),FontWeight=FontWeights.Bold};var s=new TextBlock{Text=$"{pct}% - {state.ToUpperInvariant()}",Foreground=B(state),FontWeight=FontWeights.Bold,HorizontalAlignment=HorizontalAlignment.Right};Grid.SetColumn(s,1);var bar=new ProgressBar{Minimum=0,Maximum=100,Value=pct,Height=9,Margin=new Thickness(0,2,0,1),Foreground=B(state)};Grid.SetRow(bar,1);Grid.SetColumnSpan(bar,2);var dt=new TextBlock{Text=detail,Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString("#AFC2D0")),FontSize=10};Grid.SetRow(dt,2);Grid.SetColumnSpan(dt,2);g.Children.Add(n);g.Children.Add(s);g.Children.Add(bar);g.Children.Add(dt);HealthPanel.Children.Add(g);}var ts=DateTimeOffset.Parse(r.GetProperty("timestamp").GetString()??DateTimeOffset.Now.ToString("o")).ToLocalTime();var count=r.GetProperty("protected_files").GetInt32();StatusText.Text=error?"STATUS: ATTENTION REQUIRED":repairable?"STATUS: REPAIR AVAILABLE":"STATUS: RECOVERY KEY READY";StatusText.Foreground=B(overall);StatusBorder.BorderBrush=B(overall);CurrentStateText.Text=error?"BLOCKED / FAILED":repairable?"MONITORING — REPAIRABLE":"MONITORING — HEALTHY";ReadyText.Text=error?"BLOCKED":repairable?"ATTENTION":"VERIFIED / READY";ReadyText.Foreground=B(overall);DetailText.Text=error?"A recovery channel failed or is blocked. Review details.":repairable?"Source is verified; one or more bounded repairs are available.":"All recovery channels verified.";OverallText.Text=$"{avg}% — {overall.ToUpperInvariant()}";OverallText.Foreground=B(overall);OverallBar.Value=avg;OverallBar.Foreground=B(overall);DeviceText.Text=$"{Drive} | PROMETHEUS | {count} protected files";VerifiedText.Text=$"Last verified: {ts:G}";DriveText.Text=$"PRK: {Drive}\\";FileText.Text=$"Protected files: {count}";SummaryText.Text=string.Join(Environment.NewLine,states.Select(c=>$"• {c.GetProperty("name").GetString()?.Replace("_"," ")} — {c.GetProperty("state").GetString()}"));EjectStateText.Text="MOUNTED / ACTIVE";EjectStateText.Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString("#57C7FF"));LogText.Text=$"{DateTime.Now:G} — Health refresh complete: {overall}."; }
 void SetError(string msg){StatusText.Text="STATUS: CONTROLLER ERROR";StatusText.Foreground=B("error");StatusBorder.BorderBrush=B("error");CurrentStateText.Text="FAILED";DetailText.Text=msg;LogText.Text=$"{DateTime.Now:G} — ERROR: {msg}";}
 async Task DoRecovery(string label,string action,bool confirm=false){if(confirm&&MessageBox.Show($"{label} may update Windows-side recovery support. Continue?","Prometheus PRK",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;Busy(label);try{var output=await RunRecoveryAsync(action);LogText.Text=$"{DateTime.Now:G} — {label} completed.\n{output.Trim()}";await RefreshHealthAsync();}catch(Exception ex){SetError(ex.Message);Enable();}}
 async void Diagnostics_Click(object s,RoutedEventArgs e)=>await DoRecovery("Running diagnostics","diagnose"); async void Verify_Click(object s,RoutedEventArgs e){Busy("Verifying recovery key");try{var output=await RunRecoveryAsync("verify");LogText.Text=$"{DateTime.Now:G} — Verification complete.\n{output.Trim()}";await RefreshHealthAsync();}catch(Exception ex){SetError(ex.Message);Enable();}} async void Stage_Click(object s,RoutedEventArgs e)=>await DoRecovery("Staging recovery","stage"); async void Bootstrap_Click(object s,RoutedEventArgs e)=>await DoRecovery("Bootstrapping Windows host","bootstrap",true);
 async void Repair_Click(object s,RoutedEventArgs e){if(MessageBox.Show("Run bounded self-repair using only manifest-verified PRK sources? Protected PRK corruption will remain blocked.","Prometheus PRK Self-Repair",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;Busy("Running self-repair");try{var output=await RunEngineAsync("repair");LogText.Text=$"{DateTime.Now:G} — Self-repair complete.\n{output.Trim()}";await RefreshHealthAsync();}catch(Exception ex){SetError(ex.Message);Enable();}}
 void Logs_Click(object s,RoutedEventArgs e){try{Directory.CreateDirectory(Path.GetDirectoryName(Log)!);if(!File.Exists(Log))File.WriteAllText(Log,"");Process.Start(new ProcessStartInfo("notepad.exe",$"\"{Log}\""){UseShellExecute=true});}catch(Exception ex){SetError(ex.Message);}} async void Refresh_Click(object s,RoutedEventArgs e)=>await RefreshHealthAsync();
 async void Eject_Click(object s,RoutedEventArgs e){if(MessageBox.Show("Verify and stage recovery, then close PRK-backed processes and remote management last?","Prepare Recovery Key for Eject",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;Busy("Preparing for eject");EjectStateText.Text="PREPARING…";EjectStateText.Foreground=B("working");try{using(var j=JsonDocument.Parse(await RunEngineAsync("health"))){if(!j.RootElement.GetProperty("source_verified").GetBoolean())throw new Exception("Eject blocked: Recovery Key integrity verification failed.");}await RunRecoveryAsync("stage");Directory.CreateDirectory(Local);var eject=Path.Combine(Local,"Prometheus-Removable-Eject.ps1");File.Copy(Path.Combine(Root,"tools","Prometheus-Removable-Eject.ps1"),eject,true);var handoff=Path.Combine(Local,"PRK-Eject-Handoff.ps1");File.WriteAllText(handoff,$"param([string]$Drive)\r\n$ErrorActionPreference='Stop'\r\n& powershell.exe -NoProfile -ExecutionPolicy Bypass -File '{eject.Replace("'","''")}' -Drive $Drive\r\nexit $LASTEXITCODE\r\n");EjectStateText.Text="READYING HANDOFF";Process.Start(new ProcessStartInfo("powershell.exe",$"-NoProfile -ExecutionPolicy Bypass -File \"{handoff}\" -Drive \"{Drive}\""){UseShellExecute=true,WorkingDirectory=Local});StatusText.Text="STATUS: EJECT HANDOFF STARTED";DetailText.Text="Recovery is staged on C:. Windows-side handoff is closing PRK-backed processes. Wait for safe removal.";Close();}catch(Exception ex){EjectStateText.Text="MOUNTED / ACTIVE";SetError(ex.Message);Enable();}}
}